export interface ConnectorConfig {
  /** Shopify webhook shared secret for HMAC-SHA256 verification (from X-Shopify-Hmac-SHA256 header) */
  shopifyWebhookSecret: string
  /** Airtable Personal Access Token or API Key */
  airtableApiKey: string
  /** Airtable Base ID (e.g., appXXXXXXXXXXXXXX) */
  airtableBaseId: string
  /** Airtable Table Name or ID */
  airtableTableName: string
  /** Injected fetch for testing; defaults to global fetch */
  fetch?: typeof fetch
}

export interface ShopifyOrderPaidPayload {
  ucp: {
    version: string
    capabilities: Record<string, Array<{ version: string }>>
  }
  id: string
  label: string
  currency: string
  totals: Array<{
    type: string
    display_text: string
    amount: number
  }>
  line_items: unknown[]
  fulfillment: Record<string, unknown>
  /** Customer email - not in documented example but present in real payloads */
  email?: string
  /** Additional fields that may be present */
  [key: string]: unknown
}

export interface HandleResult {
  createdRecordIds: string[]
  airtableResponse: {
    records: Array<{
      id: string
      fields: Record<string, unknown>
      createdTime: string
    }>
  }
}

