function extractTotalPrice(totals: ShopifyOrderPaidPayload['totals']): number {
  const total = totals.find(t => t.type === 'total')
  if (!total) {
    throw new Error('Missing total amount in payload totals array')
  }
  // Shopify amounts are in cents (integer), convert to decimal
  return total.amount / 100
}

function extractEmail(payload: ShopifyOrderPaidPayload): string {
  if (!payload.email) {
    throw new Error('Missing required field: email (customer email address)')
  }
  return payload.email
}

export async function handle(
  payload: ShopifyOrderPaidPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required fields
  if (!payload.id) {
    throw new Error('Missing required field: id (Shopify order ID)')
  }
  if (!payload.totals || !Array.isArray(payload.totals)) {
    throw new Error('Missing required field: totals array')
  }

  const orderId = payload.id
  const email = extractEmail(payload)
  const total = extractTotalPrice(payload.totals)

  // Build Airtable request
  const url = `https://api.airtable.com/v0/${config.airtableBaseId}/${encodeURIComponent(config.airtableTableName)}`
  const body = {
    records: [
      {
        fields: {
          'Order ID': orderId,
          'Customer Email': email,
          'Total': total
        }
      }
    ]
  }

  const fetchFn = config.fetch ?? fetch
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.airtableApiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} at POST ${url} - ${errorText}`)
  }

  const data = await response.json() as HandleResult['airtableResponse']
  const createdRecordIds = data.records.map(r => r.id)

  return {
    createdRecordIds,
    airtableResponse: data
  }
}

