        { type: 'fee', display_text: 'fee', amount: 0 },
        { type: 'total', display_text: 'total', amount: 7977 }
      ],
      line_items: [],
      fulfillment: {},
      email: 'customer@example.com'
    }
  })

  it('happy path: creates record with correct field mapping and auth', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.airtable.com/v0/appABCDEFGHIJKL/Orders')
      expect(req.headers.get('authorization')).toBe('Bearer pat_test_123')
