            'Total': 79.77
          }
        }]
      })
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const result = await handle(validPayload, { ...baseConfig, fetch })
    expect(result.createdRecordIds).toEqual(['recXXXXXXXXXXXXXX'])
    expect(calls).toHaveLength(1)
